"""Configuration loading and checkpoint geometry validation."""
from __future__ import annotations

import copy
import math
from pathlib import Path

import torch
import yaml

__all__ = ["DEFAULT_CONFIG", "load_config", "resolve_geometry", "validate_dit_state_dict"]

DEFAULT_CONFIG = {
    "dit": {
        "latent_channels": 128,
        "latent_length": 375,
        "patch_size": 8,
        "dim": 256,
        "depth": 4,
        "num_heads": 4,
    }
}

def load_config(path):
    if path is None:
        return copy.deepcopy(DEFAULT_CONFIG)
    p = Path(path)
    cfg = copy.deepcopy(DEFAULT_CONFIG)
    loaded = yaml.safe_load(p.read_text()) or {}
    for section, values in loaded.items():
        if isinstance(values, dict) and section in cfg:
            cfg[section].update(values)
        else:
            cfg[section] = values
    return cfg

def resolve_geometry(cfg, overrides=None):
    dit = dict(cfg["dit"])
    for key, value in (overrides or {}).items():
        if value is not None:
            dit[key] = value
    patch = dit["patch_size"]
    length = dit["latent_length"]
    geo = {**dit, "num_patches": math.ceil(length / patch)}
    return geo

def validate_dit_state_dict(state_dict, latent_channels, latent_length, patch_size):
    w = state_dict.get("patch_embed.weight")
    pos = state_dict.get("pos_embed")
    dim = w.shape[0]
    expected_pos = (1, math.ceil(latent_length / patch_size), dim)
    if tuple(w.shape) != (dim, latent_channels, patch_size): raise ValueError(f"patch_embed.weight shape {tuple(w.shape)} does not match geometry (dim={dim}, latent_channels={latent_channels}, patch_size={patch_size})")
    if tuple(pos.shape) != expected_pos:
        raise ValueError(
            f"pos_embed shape {tuple(pos.shape)} does not match declared "
            f"geometry (latent_length={latent_length}, patch_size={patch_size} -> {expected_pos}); "
            "rebuild the DiT with the checkpoint's true latent_length or interpolate "
            "the position table before loading"
        )
